public void SynchronousRoundTripAfterConnectAsync()
{
for (int i = 0; i < OperationsPerInvoke; i++)
{
_client.Send(_buffer);
_client.Receive(_buffer);
}
}
private void EchoLoop()
{
var buffer = new byte[1];
while (_server.Receive(buffer) != 0)
_server.Send(buffer);
}
}

